int sc_dummy() {   
    return 1000;
}

int hack() {        
        int x = AI_ul_RealResolveOneRefObject(0x620031e5);
        AI_EvalFunc_VIEWAssignObject_C((tGameObjectMain*)x, 0);
        return 1000;
}

int hackViewActorSelector = 0;

int levelHack() {
    int _pj_cam = AI_ul_RealResolveOneRefObject(0x71003F56u);
    int INV_reference_WP = AI_ul_RealResolveOneRefObject(0x620013B8u); // INV WP (group), board panel calls it in original game
    AI_EvalFunc_GRPInactiveSet_C((tGameObjectMain*)INV_reference_WP, 1); // disable inventory menu
    Vec3 v;

    AI_EvalFunc_VIEWAssignObject_C((tGameObjectMain * )_pj_cam, 0);

    //DBG_OutputDebugString("WK: %x\n", AI_EvalFunc_WORGetKey_C());

    //Vec3* v2 = OBJ_pst_GetPos((tGameObjectMain*)_pj_cam);

    if (AI_EvalFunc_WORGetKey_C() == 0xd9005833) {
        Vec3 v2;

        if (AI_EvalFunc_IoButtonJustPressed_C(0)) hackViewActorSelector = !hackViewActorSelector;

        if (hackViewActorSelector) {
            // peyj
            v2.x = -1.5f;
            v2.y = 1.5f;
            v2.z = 0.25f;
        }
        else {
            // sally
            v2.x = -1.05f;
            v2.y = -0.57f; // ez a z igazabol
            v2.z = 7.0;
        }
        OBJ_SetAbsolutePosition((tGameObjectMain*)_pj_cam, &v2);
        // eddig
    }
    else {

        //v2->z = (TIM_gf_dt / 6.0f) + v2->z;
        //OBJ_SetAbsolutePosition((tGameObjectMain*)_pj_cam, &v2);

        v.x = 74.52093f;
        v.y = 20.953468f;
        v.z = 61.516752f;
        OBJ_SetAbsolutePosition((tGameObjectMain*)_pj_cam, &v);
        AI_EvalFunc_OBJRotateGlobalZ_C((tGameObjectMain*)_pj_cam, TIM_gf_dt/4.0f);
    }
    //AI_EvalFunc_WORColorAmbiantSet_C(0, 0x7b723c);
    //AI_EvalFunc_WORColorAmbiant2Set_C(0, 0x908854);
    return 1000;
}

int script_obj_destroy()
{
    int result; // eax
    int v1; // [esp+4h] [ebp-8h]

    v1 = AI_EvalFunc_OBJDestroy_C(AI_gpst_CurrentGameObject);
    if (v1 == 1000)
        result = 1000;
    else
        result = v1;
    return result;
}

//================================================

/* Every row of AI2C_gat_fctdefs now points here.
 *
 * The transcriptions in this file were written from the demo, and
 * 1058 of the rows pointed at sc_dummy, which returned 1000 and said
 * nothing at all -- so a behaviour with no implementation looked
 * exactly like one that ran. Each key now names itself in the debug
 * output the first time the engine asks for it, and once only:
 * SC_MISSING gives every key a flag of its own, so a behaviour called
 * every frame costs one line in a lifetime.
 *
 * The transcribed function each row used to name is kept in the
 * comment beside it, and its body is still in this file, so putting
 * one back is a one-line edit.
 *
 * Note what this means in AI_ul_LoadOneAI: a row sets funcPtr, and a
 * behaviour with funcPtr set does not get its nodes loaded. So a key
 * that is neither sideloaded nor listed in interpret.txt now does
 * nothing at all rather than running the demo transcription.
 * sideload.example/README.md says how to supply the retail script.
 */
#define SC_MISSING(hexkey)                                                 \
    static int sc_seen_##hexkey = 0;                                       \
    static int sc_missing_##hexkey(void)                                   \
    {                                                                      \
        if (!sc_seen_##hexkey)                                             \
        {                                                                  \
            sc_seen_##hexkey = 1;                                          \
            DBG_OutputDebugString("AI2C: behaviour 0x%08x has no "         \
                                  "implementation\n", 0x##hexkey);         \
        }                                                                  \
        return 1000;                                                       \
    }


